[CmdletBinding(SupportsShouldProcess=$true,ConfirmImpact='High')]
param(
  [ValidateSet('Check','Capture','DryRun','Apply','Verify','VerifyReboot','Rollback')][string]$Action='Check',
  [string]$StatePath="$PSScriptRoot\state.json",
  [string]$LogPath="$PSScriptRoot\events.jsonl"
)
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
$ServiceName='HPTouchpointAnalyticsService'
$MinimumSafeVersion=[version]'4.2.2439.0'
$ServiceKey="HKLM:\SYSTEM\CurrentControlSet\Services\$ServiceName"
$ProtectedServices=@('WinDefend','mpssvc','wuauserv','UsoSvc','BITS','TermService','Tailscale')

function Write-Event([string]$Event,[string]$Result,[hashtable]$Data){$dir=Split-Path $LogPath -Parent;if($dir -and !(Test-Path -LiteralPath $dir)){New-Item -ItemType Directory -Path $dir -Force|Out-Null};[ordered]@{schemaVersion=3;utc=(Get-Date).ToUniversalTime().ToString('o');experiment='EXP-024';action=$Action;event=$Event;result=$Result;computer=$env:COMPUTERNAME;userSid=[System.Security.Principal.WindowsIdentity]::GetCurrent().User.Value;data=$Data}|ConvertTo-Json -Compress -Depth 12|Add-Content -LiteralPath $LogPath -Encoding UTF8}
function Test-Elevation{$p=New-Object Security.Principal.WindowsPrincipal([System.Security.Principal.WindowsIdentity]::GetCurrent());if(!$p.IsInRole([System.Security.Principal.WindowsBuiltInRole]::Administrator)){throw 'Elevation required'}}
function Get-ExecutablePath([string]$PathName){if([string]::IsNullOrWhiteSpace($PathName)){throw 'Service binary path missing'};if($PathName.TrimStart().StartsWith('"')){$m=[regex]::Match($PathName,'^\s*"([^"]+)"');if(!$m.Success){throw 'Unable to parse quoted service executable path'};return $m.Groups[1].Value};$m=[regex]::Match($PathName,'^\s*([^\s]+\.exe)',[System.Text.RegularExpressions.RegexOptions]::IgnoreCase);if(!$m.Success){throw 'Unable to parse service executable path'};$m.Groups[1].Value}
function Get-RegistryValueState([string]$Name){if(!(Test-Path -LiteralPath $ServiceKey)){throw 'Service registry key missing'};$key=Get-Item -LiteralPath $ServiceKey;if($key.GetValueNames() -notcontains $Name){return [pscustomobject]@{Exists=$false;Kind=$null;Data=$null}};[pscustomobject]@{Exists=$true;Kind=$key.GetValueKind($Name).ToString();Data=$key.GetValue($Name,$null,[Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)}}
function Get-DelayedNumeric($Candidate){if($Candidate.DelayedAutoStart.Exists){return [int]$Candidate.DelayedAutoStart.Data};0}
function Get-PendingReboot{$paths=@('HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending','HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired');foreach($p in $paths){if(Test-Path -LiteralPath $p){return $true}};$sm='HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager';try{$v=(Get-ItemProperty -LiteralPath $sm -Name PendingFileRenameOperations -ErrorAction Stop).PendingFileRenameOperations;if($v){return $true}}catch [System.Management.Automation.ItemNotFoundException]{};$false}
function Get-MdmEnrollmentDetected{$root='HKLM:\SOFTWARE\Microsoft\Enrollments';if(!(Test-Path -LiteralPath $root)){return $false};foreach($k in Get-ChildItem -LiteralPath $root -ErrorAction SilentlyContinue){try{$p=Get-ItemProperty -LiteralPath $k.PSPath -ErrorAction Stop;if($p.ProviderID -or $p.UPN -or $p.DiscoveryServiceFullURL){return $true}}catch{}};$false}
function Get-ManagementState{$cs=Get-CimInstance Win32_ComputerSystem;[pscustomobject]@{DomainJoined=[bool]$cs.PartOfDomain;MdmEnrollment=[bool](Get-MdmEnrollmentDetected);ConfigMgr=[bool](Get-Service CcmExec -ErrorAction SilentlyContinue)}}
function Get-ProtectedState{$rows=@();foreach($name in $ProtectedServices){$s=Get-CimInstance Win32_Service -Filter "Name='$name'" -ErrorAction SilentlyContinue;if($s){$rows+=[pscustomobject]@{Name=$s.Name;State=$s.State;StartMode=$s.StartMode;PathName=$s.PathName}}};[pscustomobject]@{Services=@($rows|Sort-Object Name)}}
function Get-PackageIdentity{
  $roots=@('HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*','HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*')
  $matches=@(foreach($root in $roots){Get-ItemProperty $root -ErrorAction SilentlyContinue|Where-Object {$_.DisplayName -match '(?i)HP.*(Touchpoint.*Analytics|Device Health)' -and $_.Publisher -match '(?i)HP Inc|Hewlett-Packard'}|ForEach-Object {[pscustomobject]@{ProductKey=$_.PSChildName;DisplayName=$_.DisplayName;DisplayVersion=$_.DisplayVersion;Publisher=$_.Publisher;InstallLocation=$_.InstallLocation;UninstallString=$_.UninstallString}}})
  $unique=@($matches|Sort-Object ProductKey,DisplayName,DisplayVersion -Unique);if($unique.Count -ne 1){throw 'HP Touchpoint package identity absent or ambiguous'};$unique[0]
}
function Get-ServiceTriggerState{$root=Join-Path $ServiceKey 'TriggerInfo';if(!(Test-Path -LiteralPath $root)){return @()};@((Get-ChildItem -LiteralPath $root -ErrorAction Stop|Sort-Object PSChildName|ForEach-Object{$k=$_;$props=Get-ItemProperty -LiteralPath $k.PSPath;[pscustomobject]@{Name=$k.PSChildName;Type=$props.Type;Action=$props.Action;GUID=if($props.PSObject.Properties.Name -contains 'GUID'){[Convert]::ToBase64String([byte[]]$props.GUID)}else{$null};Data=if($props.PSObject.Properties.Name -contains 'Data'){[Convert]::ToBase64String([byte[]]$props.Data)}else{$null}}}))}
function Test-Same($A,$B){($A|ConvertTo-Json -Compress -Depth 12) -eq ($B|ConvertTo-Json -Compress -Depth 12)}
function Get-Candidate{
  Test-Elevation;$os=Get-CimInstance Win32_OperatingSystem;$cs=Get-CimInstance Win32_ComputerSystem;$bios=Get-CimInstance Win32_BIOS
  if($os.Caption -notmatch 'Windows 11' -or $cs.Manufacturer -notmatch 'HP|Hewlett-Packard'){throw 'Unsupported platform'};if(Get-PendingReboot){throw 'Pending reboot detected'}
  $management=Get-ManagementState;if($management.DomainJoined){throw 'Enterprise-managed domain state refused'};if($management.MdmEnrollment){throw 'Enterprise MDM enrollment refused'};if($management.ConfigMgr){throw 'Enterprise ConfigMgr ownership refused'}
  $matches=@(Get-CimInstance Win32_Service -Filter "Name='$ServiceName'" -ErrorAction SilentlyContinue);if($matches.Count -ne 1){throw 'Candidate service absent or ambiguous'};$svc=$matches[0]
  if($svc.DisplayName -notmatch '(?i)HP.*Touchpoint.*Analytics'){throw 'Service display identity refused'};if($svc.PathName -notmatch '(?i)HP.*Touchpoint|Touchpoint.*Analytics'){throw 'Service executable identity refused'};if($svc.PathName -match '(?i)Defender|SecurityHealth|Tailscale|Omnissa|RemoteDesktop|WindowsApp'){throw 'Protected identity refused'};if($svc.ServiceType -match '(?i)driver'){throw 'Driver-backed service refused'};if($svc.StartMode -eq 'Disabled'){throw 'Disabled service refused'}
  $exe=Get-ExecutablePath $svc.PathName;if(!(Test-Path -LiteralPath $exe -PathType Leaf)){throw 'Service executable missing'};$sig=Get-AuthenticodeSignature -LiteralPath $exe;if($sig.Status -ne 'Valid' -or !$sig.SignerCertificate -or $sig.SignerCertificate.Subject -notmatch '(?i)HP Inc|Hewlett-Packard'){throw 'HP publisher signature refused'}
  $rawVersion=(Get-Item -LiteralPath $exe).VersionInfo.FileVersion;try{$version=[version]($rawVersion -replace '[^0-9\.]','')}catch{throw 'Executable version unreadable'};if($version -lt $MinimumSafeVersion){throw "Outdated HP Touchpoint Analytics version refused: $version"};$hash=(Get-FileHash -LiteralPath $exe -Algorithm SHA256).Hash
  $package=Get-PackageIdentity;if($package.DisplayVersion){try{$packageVersion=[version]($package.DisplayVersion -replace '[^0-9\.]','');if($packageVersion -lt $MinimumSafeVersion){throw "Outdated HP Touchpoint package version refused: $packageVersion"}}catch [System.Management.Automation.RuntimeException]{throw}}
  $gs=Get-Service -Name $ServiceName;$deps=@($gs.ServicesDependedOn|ForEach-Object Name|Sort-Object);$dependents=@($gs.DependentServices|ForEach-Object Name|Sort-Object);foreach($name in @($deps+$dependents)){if($name -match '(?i)WinDefend|mpssvc|bfe|wuauserv|bits|cryptsvc|Tailscale|Omnissa|TermService'){throw "Protected dependency refused: $name"}}
  $protected=Get-ProtectedState;foreach($required in 'wuauserv','BITS'){$row=@($protected.Services|Where-Object Name -eq $required);if(!$row.Count){throw "Windows Update dependency missing: $required"};if($row[0].StartMode -eq 'Disabled'){throw "Windows Update dependency disabled: $required"}}
  [pscustomobject]@{Service=$svc;Executable=$exe;Version=$version.ToString();Hash=$hash;SignatureSubject=$sig.SignerCertificate.Subject;Package=$package;DelayedAutoStart=(Get-RegistryValueState 'DelayedAutoStart');RegistryStart=(Get-RegistryValueState 'Start');FailureActions=(Get-RegistryValueState 'FailureActions');Triggers=(Get-ServiceTriggerState);Dependencies=$deps;Dependents=$dependents;WindowsBuild=$os.BuildNumber;BIOS=$bios.SMBIOSBIOSVersion;Management=$management;Protected=$protected}
}
function Assert-BaselineEligible($c){if($c.Service.StartMode -notin @('Auto','Automatic')){throw 'Baseline startup mode must be Automatic or Automatic Delayed Start'}}
function Save-State($c){if(Test-Path -LiteralPath $StatePath){throw 'State overwrite refused'};$dir=Split-Path $StatePath -Parent;if($dir -and !(Test-Path -LiteralPath $dir)){New-Item -ItemType Directory -Path $dir -Force|Out-Null};$svc=$c.Service;$state=[ordered]@{schema=3;computer=$env:COMPUTERNAME;userSid=[System.Security.Principal.WindowsIdentity]::GetCurrent().User.Value;service=$svc.Name;displayName=$svc.DisplayName;path=$svc.PathName;executable=$c.Executable;executableVersion=$c.Version;executableHash=$c.Hash;signatureSubject=$c.SignatureSubject;package=$c.Package;startMode=$svc.StartMode;registryStart=$c.RegistryStart;delayedAutoStart=(Get-DelayedNumeric $c);delayedAutoStartRegistry=$c.DelayedAutoStart;failureActions=$c.FailureActions;triggers=$c.Triggers;state=$svc.State;serviceAccount=$svc.StartName;dependencies=@($c.Dependencies);dependents=@($c.Dependents);windowsBuild=$c.WindowsBuild;bios=$c.BIOS;management=$c.Management;protected=$c.Protected;capturedBootTime=(Get-CimInstance Win32_OperatingSystem).LastBootUpTime.ToUniversalTime().ToString('o');capturedUtc=(Get-Date).ToUniversalTime().ToString('o');evidenceStatus='needs-evidence'};$state|ConvertTo-Json -Depth 12|Set-Content -LiteralPath $StatePath -Encoding UTF8;Write-Event 'state-captured' 'pass' @{service=$svc.Name;startMode=$svc.StartMode;delayedAutoStart=(Get-DelayedNumeric $c);state=$svc.State;version=$c.Version;hash=$c.Hash;package=$c.Package};$state}
function Read-State{if(!(Test-Path -LiteralPath $StatePath)){throw 'State file missing'};$s=Get-Content -LiteralPath $StatePath -Raw|ConvertFrom-Json;if($s.schema -ne 3 -or $s.computer -ne $env:COMPUTERNAME -or $s.userSid -ne [System.Security.Principal.WindowsIdentity]::GetCurrent().User.Value -or $s.service -ne $ServiceName){throw 'State identity refused'};$s}
function Restore-RegistryValue([string]$Name,$State){$key=Get-Item -LiteralPath $ServiceKey;if([bool]$State.Exists){$kind=[Enum]::Parse([Microsoft.Win32.RegistryValueKind],[string]$State.Kind,$true);$key.SetValue($Name,$State.Data,$kind)}elseif($key.GetValueNames() -contains $Name){Remove-ItemProperty -LiteralPath $ServiceKey -Name $Name}}
function Set-TreatmentMode{Set-Service -Name $ServiceName -StartupType Manual;Set-ItemProperty -LiteralPath $ServiceKey -Name DelayedAutoStart -Type DWord -Value 0}
function Restore-StartupState($s){Set-Service -Name $ServiceName -StartupType Automatic;Restore-RegistryValue 'Start' $s.registryStart;Restore-RegistryValue 'DelayedAutoStart' $s.delayedAutoStartRegistry}
function Assert-DriftSafe($s,$c){if($c.Service.PathName -ne $s.path){throw 'Rollback service identity changed'};if($c.Executable -ne $s.executable){throw 'Rollback executable identity changed'};if($c.Hash -ne $s.executableHash){throw 'Rollback executable hash changed'};if($c.Version -ne $s.executableVersion){throw 'Rollback executable version changed'};if($c.SignatureSubject -ne $s.signatureSubject){throw 'Rollback publisher identity changed'};if(!(Test-Same $c.Package $s.package)){throw 'Rollback package identity changed'};if(!(Test-Same $c.FailureActions $s.failureActions)){throw 'Rollback recovery actions changed'};if(!(Test-Same $c.Triggers $s.triggers)){throw 'Rollback service triggers changed'};if(Compare-Object @($c.Dependencies) @($s.dependencies)){throw 'Rollback dependencies changed'};if(Compare-Object @($c.Dependents) @($s.dependents)){throw 'Rollback dependents changed'};if(!(Test-Same $c.Management $s.management)){throw 'Rollback management state changed'};if(!(Test-Same $c.Protected $s.protected)){throw 'Rollback protected state changed'}}
function Test-Treatment($c){$c.Service.StartMode -eq 'Manual' -and [bool]$c.DelayedAutoStart.Exists -and [int]$c.DelayedAutoStart.Data -eq 0}
function Test-OriginalStartup($c,$s){($c.Service.StartMode -eq $s.startMode) -and (Test-Same $c.RegistryStart $s.registryStart) -and (Test-Same $c.DelayedAutoStart $s.delayedAutoStartRegistry)}

try{$candidate=Get-Candidate;$svc=$candidate.Service;switch($Action){
 'Check'{Write-Event 'supported' 'pass' @{service=$svc.Name;path=$svc.PathName;startMode=$svc.StartMode;delayedAutoStart=(Get-DelayedNumeric $candidate);version=$candidate.Version;hash=$candidate.Hash;package=$candidate.Package;management=$candidate.Management};[pscustomobject]@{Supported=$true;Name=$svc.Name;DisplayName=$svc.DisplayName;PathName=$svc.PathName;StartMode=$svc.StartMode;DelayedAutoStart=(Get-DelayedNumeric $candidate);State=$svc.State;Version=$candidate.Version;SHA256=$candidate.Hash;Package=$candidate.Package;EvidenceStatus='needs-evidence'}}
 'Capture'{Assert-BaselineEligible $candidate;$s=Save-State $candidate;Write-Event 'capture' 'pass' @{statePath=$StatePath};$s}
 'DryRun'{Assert-BaselineEligible $candidate;$r=[pscustomobject]@{WouldChange=$true;MutationCount=1;Service=$ServiceName;From=$svc.StartMode;To='Manual';PreserveRunningState=$true;RebootPersistenceRequired=$true;Rollback='Restore exact captured Start and DelayedAutoStart registry existence, type, data, startup mode, and original running state.';EvidenceStatus='needs-evidence'};Write-Event 'dry-run' 'pass' @{from=$svc.StartMode;to='Manual';preserveRunningState=$true};$r}
 'Apply'{$s=Read-State;Assert-DriftSafe $s $candidate;if(Test-Treatment $candidate){Write-Event 'already-applied' 'idempotent' @{service=$svc.Name};break};if(!(Test-OriginalStartup $candidate $s)){throw 'Apply configuration drift detected'};$running=$svc.State;if($WhatIfPreference){Write-Event 'apply' 'whatif' @{service=$svc.Name;proposedStartMode='Manual';preserveRunningState=$running};$null=$PSCmdlet.ShouldProcess($ServiceName,'Set startup mode to Manual');break};if($PSCmdlet.ShouldProcess($ServiceName,'Set startup mode to Manual while preserving current running state')){Set-TreatmentMode}else{Write-Event 'apply-declined' 'declined' @{service=$svc.Name};break};$after=Get-Candidate;if(!(Test-Treatment $after) -or $after.Service.State -ne $running){throw 'Apply verification failed'};Write-Event 'applied' 'pass' @{before=$svc.StartMode;after=$after.Service.StartMode;runningStatePreserved=$running}}
 'Verify'{$s=Read-State;Assert-DriftSafe $s $candidate;if(!(Test-Treatment $candidate)){throw 'Verification failed'};Write-Event 'verified' 'pass' @{manual=$true;version=$candidate.Version;hash=$candidate.Hash};$true}
 'VerifyReboot'{$s=Read-State;Assert-DriftSafe $s $candidate;$boot=(Get-CimInstance Win32_OperatingSystem).LastBootUpTime.ToUniversalTime();if($boot -le [datetime]$s.capturedBootTime){throw 'A later boot is required for reboot persistence verification'};if(!(Test-Treatment $candidate)){throw 'Reboot persistence failed'};Write-Event 'reboot-verified' 'pass' @{boot=$boot.ToString('o');manual=$true;state=$candidate.Service.State;version=$candidate.Version;hash=$candidate.Hash;evidenceStatus='needs-evidence'};$true}
 'Rollback'{$s=Read-State;Assert-DriftSafe $s $candidate;if((Test-OriginalStartup $candidate $s) -and $candidate.Service.State -eq $s.state){Write-Event 'rolled-back' 'idempotent' @{service=$svc.Name};break};if(!(Test-Treatment $candidate)){throw 'Rollback collision or startup configuration drift detected'};if($WhatIfPreference){Write-Event 'rollback' 'whatif' @{service=$svc.Name;restoreStartMode=$s.startMode;restoreDelayedAutoStart=$s.delayedAutoStartRegistry;restoreState=$s.state};$null=$PSCmdlet.ShouldProcess($ServiceName,'Restore exact captured startup and running state');break};if($PSCmdlet.ShouldProcess($ServiceName,'Restore exact captured startup and running state')){Restore-StartupState $s;$status=(Get-Service $ServiceName).Status;if($s.state -eq 'Running' -and $status -ne 'Running'){Start-Service $ServiceName}elseif($s.state -eq 'Stopped' -and $status -eq 'Running'){Stop-Service $ServiceName}}else{Write-Event 'rollback-declined' 'declined' @{service=$svc.Name};break};$after=Get-Candidate;if(!(Test-OriginalStartup $after $s) -or $after.Service.State -ne $s.state){throw 'Exact rollback verification failed'};Write-Event 'rolled-back' 'pass' @{restoredExactOriginal=$true;startMode=$after.Service.StartMode;delayedAutoStart=(Get-DelayedNumeric $after);state=$after.Service.State;version=$after.Version;hash=$after.Hash};$after}
}}catch{try{Write-Event 'failure' 'failure' @{stage=$Action;message=$_.Exception.Message;type=$_.Exception.GetType().FullName}}catch{};throw}
